def gen(rng):
    def fmt(a, k):
        return f'{len(a)} {k}\n' + ' '.join(map(str, a))
    tests = [fmt([5], 5), fmt([5], 1), fmt([1, 7, 3, 9, 2, 8], 4), fmt([7, 1, 9, 2, 8, 3, 9, 4], 5),
             fmt([5, 6, 7, 8], 1), fmt([1, 2, 3, 9, 9], 5), fmt([9, 1, 1, 9, 1, 1, 9], 1),
             fmt([1, 9, 9, 9, 1], 1), fmt([10**9, 1, 10**9], 10**9)]
    for _ in range(45):
        n = rng.randint(1, 10)
        a = [rng.randint(1, 10) for _ in range(n)]
        tests.append(fmt(a, rng.randint(1, 10)))
    N = 200000
    for frac in (0.5, 0.3, 0.01, 0.9):
        a = [rng.randint(1, 100) if rng.random() < frac else rng.randint(1000, 10**9) for _ in range(N)]
        tests.append(fmt(a, 500))
    tests.append(fmt([1 if i % 2 == 0 else 10**9 for i in range(N)], 5))
    return tests
